CREATE TABLE crop_milestones(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`crop_id` bigint  NOT NULL,`stage` varchar(255)  NOT NULL COMMENT 'germination, vegetative, flowering, maturation',`expected_start_date` date  NOT NULL,`expected_end_date` date  NOT NULL,`actual_start_date` date  NULL,`actual_end_date` date  NULL,`status` varchar(255)  DEFAULT 'pending' COMMENT 'pending, in_progress, completed, delayed',`progress_percentage` INT  DEFAULT 0 COMMENT 'Progress 0-100',`recommendations` text  NULL COMMENT 'JSON array of stage-specific recommendations',`notes` text  NULL,`alert_sent` TINYINT(1)  DEFAULT 0)ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;